import{d as c,C as t,o as b,c as m,j as a,a as o,E as r,a3 as p}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第四章","description":"从道冲与不盈，理解万物之宗、和光同尘及象帝之先。","frontmatter":{"title":"道德经第四章","description":"从道冲与不盈，理解万物之宗、和光同尘及象帝之先。","category":"guide","aliases":["道德经第四章","老子第四章","dao de jing chapter 4"],"source":["王弼《道德真经注》卷一"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-04.md","filePath":"daoism/dao-de-jing/chapter-04.md","lastUpdated":1794189804000}'),u={name:"daoism/dao-de-jing/chapter-04.md"},P=c({...u,setup(g){const i=[{id:"empty-and-inexhaustible",label:"道冲，而用之或不盈",showLabel:!0,sentences:[["道",{text:"冲",glossary:"chong"},"，而用之或不盈。"],["渊兮似万物之宗。"]],note:["【白话】道是虚而不满的，运用它，似乎也不会被填满。幽深啊，仿佛是万物的宗源。","【王弼注择要】「冲而用之，用乃不能穷；满以造实，实来则溢。」王弼把虚与用联系起来，以充满后容易溢出作对照，说明不盈何以能够无穷地起作用。","【读法】「冲」在这里指虚，不是冲撞。「不盈」先按不满来读，用之不竭是王弼进一步说明的作用，不能直接把盈的字义改成枯竭。"]},{id:"softening-and-mingling",label:"挫其锐，解其纷",showLabel:!0,sentences:[[{text:"挫",glossary:"cuo"},"其锐，解其纷，"],["和其光，同其尘。"]],note:["【白话】消减它的锋锐，解开它的纷结，调和它的光芒，与尘世相混同。","【王弼注择要】「和光而不污其体，同尘而不渝其真。」王弼强调，调和与混同并不使道的本体受污、真性改变。","【读法】这四句承接对道的描写。若引申为人的处事，可以想到不以锋芒压人；但不能直接将同尘解释成随波逐流、不分是非。"]},{id:"before-the-heavenly-emperor",label:"湛兮似或存",showLabel:!0,sentences:[[{text:"湛",glossary:"zhan"},"兮似或存。"],["吾不知谁之子，",{text:"象",glossary:"xiang"},{text:"帝",glossary:"di"},"之先。"]],note:["【白话】深沉啊，好像有所存在。我不知道它是谁的后代，似乎在天帝之前就已经存在。","【王弼注择要】「帝，天帝也。」王弼在比较天地与道的承载、覆育能力后，以此说明道更为根本，并非给天帝另编一段家世。","【读法】「似」「或」「不知」「象」都使语气保持试探。「谁之子」是在追问所从来，文本没有由此确定一个道的创造者。"]}],n=[{id:"chong",term:"冲",sense:1},{id:"cuo",term:"挫",sense:1},{id:"zhan",term:"湛",sense:1},{id:"xiang",term:"象",sense:1,context:"「象帝之先」中的象，作似、仿佛解，不作形象或卦象解。"},{id:"di",term:"帝",sense:1}];return(x,e)=>{const s=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return b(),m("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第四章",tabindex:"-1"},[o("道德经第四章 "),a("a",{class:"header-anchor",href:"#道德经第四章","aria-label":'Permalink to "道德经第四章"'},"​")],-1)),r(s,{title:"虚而能用，深而难名",summary:"前三章由道与名走向处事、治理，本章重新追问道怎样起作用。它用虚、渊、光、尘描写，又不断以「似」收住断言：道是万物所由，却不能被当成万物中的一个有形对象。",points:[{label:"先读",text:"冲、不盈与万物之宗怎样相连？"},{label:"再辨",text:"和光同尘为何不等于改变真性？"},{label:"后想",text:"为什么说到根源，仍保留「不知」？"}],hint:"竹简模式先通读；经典阅读可展开段释义、点击标记字词查义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段级释义",tabindex:"-1"},[o("【原典层】原文与段级释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段级释义","aria-label":'Permalink to "【原典层】原文与段级释义"'},"​")],-1)),r(l,{sections:i,glossary:n,tone:"ink",density:"comfortable","aria-label":"《道德经》第四章原文"}),e[2]||(e[2]=a("h2",{id:"【导读层】核心句引读",tabindex:"-1"},[o("【导读层】核心句引读 "),a("a",{class:"header-anchor",href:"#【导读层】核心句引读","aria-label":'Permalink to "【导读层】核心句引读"'},"​")],-1)),r(d,{lines:[{text:"道冲，而用之或不盈。",tone:"体用",guide:"虚并未使道失去作用。王弼用满则溢来衬托不盈，把根源的开放与作用的持续联系起来。"},{text:"和其光，同其尘。",tone:"相接",guide:"不以光芒自隔于万物，也不因与尘相同而失去其真。这里的调和保留了根本，不是一味退缩或迎合。"},{text:"吾不知谁之子，象帝之先。",tone:"溯源",guide:"天帝仍可以被提出来比较，道却更难追问其所从来。这是根源次序的表达，不是可以据以编排年代的历史叙事。"}]}),e[3]||(e[3]=a("h2",{id:"【注释层】字词释义",tabindex:"-1"},[o("【注释层】字词释义 "),a("a",{class:"header-anchor",href:"#【注释层】字词释义","aria-label":'Permalink to "【注释层】字词释义"'},"​")],-1)),r(h,{items:n}),e[4]||(e[4]=p('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-为什么用虚与渊来描写道" tabindex="-1">象：为什么用虚与渊来描写道？ <a class="header-anchor" href="#象-为什么用虚与渊来描写道" aria-label="Permalink to &quot;象：为什么用虚与渊来描写道？&quot;">​</a></h3><p>有形的容器一旦盛满，就不再有继续容纳的余地。本章借冲与不盈，把读者从充实、占满的想象里移开；又用渊说明其深，用宗说明万物有所由。它们是帮助进入的譬喻，不能合起来当成道是一口巨大容器的物理描述。</p><h3 id="理-和光同尘为什么还要说「不渝其真」" tabindex="-1">理：和光同尘为什么还要说「不渝其真」？ <a class="header-anchor" href="#理-和光同尘为什么还要说「不渝其真」" aria-label="Permalink to &quot;理：和光同尘为什么还要说「不渝其真」？&quot;">​</a></h3><p>若道只在远离万物之处才成立，就难以说明它如何作为万物之宗；若一进入万物便被改变，又失去了根本性。王弼以不污其体、不渝其真解释这组张力：能与万物相接，而不被某个具体形态穷尽。这是对道的说明，应用到人格修养还需再作一步引申。</p><h3 id="用-今天怎样理解「不盈」而不走向空泛" tabindex="-1">用：今天怎样理解「不盈」而不走向空泛？ <a class="header-anchor" href="#用-今天怎样理解「不盈」而不走向空泛" aria-label="Permalink to &quot;用：今天怎样理解「不盈」而不走向空泛？&quot;">​</a></h3><p>可以把它借作检查余地的提醒：知识框架是否还允许新事实进入，安排是否给变化留下空间？有余地不等于没有准备；减少无谓占满，也不意味着放弃应做的工作。这里是从譬喻引出的实践问题，不是对道的科学定义。</p><h2 id="【解读层】现代解读与启发" tabindex="-1">【解读层】现代解读与启发 <a class="header-anchor" href="#【解读层】现代解读与启发" aria-label="Permalink to &quot;【解读层】现代解读与启发&quot;">​</a></h2><p><strong>少一点证明自己，多一点化解纠结。</strong> 讨论分歧时，与其让措辞更尖锐，不如把相互混在一起的问题拆开。挫锐、解纷可启发交流方式；必要的原则、证据与责任仍需明确表达。</p><p><strong>在根本问题前保留诚实的未知。</strong> 面对超出已有证据的问题，可以先说明已知与未知，再继续追索。「吾不知」使表达不必靠一个过满的答案来维持确定感，也不妨碍持续学习。</p><h2 id="【个人记录】我的笔记" tabindex="-1">【个人记录】我的笔记 <a class="header-anchor" href="#【个人记录】我的笔记" aria-label="Permalink to &quot;【个人记录】我的笔记&quot;">​</a></h2><p>留给自己的续读问题：我在哪件事上把安排或解释填得太满？若留一点余地，是为了更好地回应变化，还是在回避必要的承担？</p><h2 id="校读说明与参考来源" tabindex="-1">校读说明与参考来源 <a class="header-anchor" href="#校读说明与参考来源" aria-label="Permalink to &quot;校读说明与参考来源&quot;">​</a></h2><ul><li>「不盈」按不满解读，另辨王弼由此说明的用不穷；「湛」在本页取深沉义，不只解作清澈。</li><li>「象帝之先」的象作似解，帝依王弼注作天帝解；不改写成一段确定的创世年代。</li></ul><p>参考：<a href="https://github.com/kanripo/KR5c0073/blob/b988441bd55861741c850e1dff4a2d4f895daf3d/KR5c0073_001.txt" target="_blank" rel="noreferrer">王弼《道德真经注》卷一 HFL 本电子录文，003a–003b</a>。</p>',15))])}}});export{_ as __pageData,P as default};
